testCases.expectedOutput:
BoundedContext Ordering {
    domain {
        Aggregate Order {
            orderId: UUID @identity
            customerId: String @required
            items: List<OrderItem>
            totalAmount: Decimal @min(0)
            status: String

            operations {
                when placing order with customerId and items:
                require that:
                    - customerId is not empty
                    - items is not empty
                then:
                    - calculate totalAmount as sum of item prices
                    - set status to "PLACED"
                emit OrderPlaced with orderId and totalAmount
            }
        }

        Entity OrderItem {
            itemId: UUID @identity
            productId: String @required
            quantity: Int @min(1)
            unitPrice: Decimal @min(0)
        }
    }

    events {
        DomainEvent OrderPlaced {
            orderId: UUID
            totalAmount: Decimal
            occurredAt: DateTime
        }
    }
}

BoundedContext Billing {
    domain {
        Aggregate Invoice {
            invoiceId: UUID @identity
            customerId: String @required
            amountDue: Money @required
            paidAmount: Money
            status: String
            paidAt: DateTime?

            operations {
                when recording payment with paymentAmount and paidAt:
                require that:
                    - paymentAmount is greater than 0
                    - status is not "PAID"
                then:
                    - calculate paidAmount as paidAmount plus paymentAmount
                    - set status to "PAID"
                    - set paidAt to paidAt
                emit InvoicePaid with invoiceId
            }
        }

        ValueObject Money {
            amount: Decimal @min(0)
            currency: String @required @maxLength(3)
        }
    }

    events {
        DomainEvent InvoicePaid {
            invoiceId: UUID
            paidAt: DateTime
            amountPaid: Money
        }
    }

    repositories {
        Repository InvoiceRepository for Invoice {
            findById(id: UUID): Invoice?
            save(invoice: Invoice): Void
        }
    }
}

BoundedContext HotelBooking {
    domain {
        Aggregate Reservation {
            reservationId: UUID @identity
            guestName: String @required
            checkIn: DateTime @required
            checkOut: DateTime @required
            status: String
            totalCost: Money

            operations {
                when confirming reservation:
                require that:
                    - status is "PENDING"
                    - checkIn is after now
                then:
                    - set status to "CONFIRMED"
                emit ReservationConfirmed with reservationId

                when cancelling reservation with reason:
                require that:
                    - status is not "CHECKED_IN"
                    - status is not "CANCELLED"
                then:
                    - set status to "CANCELLED"
                emit ReservationCancelled with reservationId and reason
            }
        }

        ValueObject Money {
            amount: Decimal @min(0)
            currency: String @required @maxLength(3)
        }
    }

    events {
        DomainEvent ReservationConfirmed {
            reservationId: UUID
            confirmedAt: DateTime
        }

        DomainEvent ReservationCancelled {
            reservationId: UUID
            reason: String
            cancelledAt: DateTime
        }
    }
}

BoundedContext Banking {
    domain {
        Aggregate Account {
            accountId: UUID @identity
            ownerName: String @required
            balance: Decimal @min(0)
            status: String

            invariants {
                "Balance cannot be negative": balance is greater than 0
                "Status must be valid": status is one of "OPEN", "FROZEN", "CLOSED"
            }

            operations {
                when depositing with amount:
                require that:
                    - amount is not empty
                    - amount is greater than 0
                then:
                    - calculate balance as balance plus amount

                when freezing account:
                require that:
                    - status is "OPEN"
                then:
                    - set status to "FROZEN"
            }
        }
    }
}

BoundedContext Logistics {
    domain {
        Aggregate Shipment {
            shipmentId: UUID @identity
            trackingNumber: String @required @unique
            destination: Address @required
            status: String
            shippedAt: DateTime?
            deliveredAt: DateTime?

            operations {
                when marking shipped:
                require that:
                    - trackingNumber is not empty
                    - destination is not empty
                    - status is "CREATED"
                then:
                    - set status to "SHIPPED"
                    - set shippedAt to now
            }
        }

        ValueObject Address {
            line1: String @required
            city: String @required
            countryCode: String @required @maxLength(2)
        }
    }

    repositories {
        Repository ShipmentRepository for Shipment {
            findById(id: UUID): Shipment?
            findByTrackingNumber(trackingNumber: String): Shipment?
            save(shipment: Shipment): Void
        }
    }

    specifications {
        Specification ActiveShipment {
            matches Shipment where:
                - status is not "DELIVERED"
                - status is not "CANCELLED"
        }
    }
}

BoundedContext Subscriptions {
    domain {
        Aggregate Subscription {
            subscriptionId: UUID @identity
            customerId: String @required
            planCode: String @required
            status: String
            currentPeriodEnd: DateTime
            cancelAtPeriodEnd: Boolean

            operations {
                when renewing subscription with nextPeriodEnd:
                require that:
                    - status is "ACTIVE"
                    - nextPeriodEnd is after currentPeriodEnd
                then:
                    - set currentPeriodEnd to nextPeriodEnd
                    - set cancelAtPeriodEnd to false
                emit SubscriptionRenewed with subscriptionId
            }
        }
    }

    events {
        DomainEvent SubscriptionRenewed {
            subscriptionId: UUID
            nextPeriodEnd: DateTime
            renewedAt: DateTime
        }
    }

    repositories {
        Repository SubscriptionRepository for Subscription {
            findByCustomerId(customerId: String): List<Subscription>
            save(subscription: Subscription): Void
        }
    }
}

BoundedContext Inventory {
    domain {
        Aggregate StockItem {
            stockItemId: UUID @identity
            sku: String @required @unique
            quantity: Int @min(0)
            reservedQuantity: Int @min(0)

            operations {
                when reserving stock with requestedQuantity:
                require that:
                    - requestedQuantity is greater than 0
                    - quantity is greater than requestedQuantity
                then:
                    - calculate quantity as quantity minus requestedQuantity
                    - calculate reservedQuantity as reservedQuantity plus requestedQuantity
                emit StockReserved with stockItemId
            }
        }

        DomainService InventoryPolicy {
            when checking reorder need with quantity as Int and reorderPoint as Int:
            then:
                - calculate reorderNeeded as quantity is less than reorderPoint
        }
    }

    events {
        DomainEvent StockReserved {
            stockItemId: UUID
            quantity: Int
            reservedAt: DateTime
        }
    }
}
